orders = await orders_get_orders()
totals = {}
for o in orders:
    r = o.get("region")
    totals[r] = totals.get(r, 0) + o.get("amount", 0)
totals = {k: round(v, 2) for k, v in totals.items()}
return {"count": len(orders), "totals": totals}
